// ***************
// Filename: feature_detect_top.sv
// Author: FPGA Cores 4 U
// Description: feature_detect with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   feature_detect_regs (u_regs, src/include/feature_detect_regs.sv, ID
//   "FEAT", VERSION and DATE at 0x00-0x08, the registers from 0x10) and the
//   logic feature_detect (u_core, src/feature_detect.sv), joined by the
//   register interface feature_detect_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from feature_detect_regs.json and the ports of
//   feature_detect: regenerate after changing either. Clock - clk. Reset -
//   synchronous active low rst_n.
// Date: 2026-10-21
module feature_detect_top #(
  parameter int MAXW = 2048,
  parameter int MAXH = 1152,
  parameter int CELL_LOG2 = 2,
  parameter int SHIFT_MAX = 4,
  parameter int CW = 16
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // s_axis: axis_if.monitor (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.monitor s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.master m_axis,
  output logic [1:0] feat_o,
  output logic done_o
);
  // register interface between the register map and the logic
  feature_detect_regs_if u_regs_if ();

  feature_detect_regs u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  feature_detect #(
    .MAXW(MAXW),
    .MAXH(MAXH),
    .CELL_LOG2(CELL_LOG2),
    .SHIFT_MAX(SHIFT_MAX),
    .CW(CW)
  ) u_core (
    .clk,
    .rst_n,
    .s_axis,
    .m_axis,
    .feat_o,
    .done_o,
    .regs(u_regs_if)
  );
endmodule
